    "title": "贵州湖南江西等地有较强降水 新一轮冷空气将自西向东影响我国大部地区",
    "link": "https://www.chinanews.com.cn/sh/2026/10-15/10714766.shtml",
    "pub_date": "2026-10-15 08:29:31",
    "author": "",
    "description": "中新网10月15日电 据中央气象台网站消息，昨日，湖南等地出现较强降雨，内蒙古中部等地有大风。预计15日，江南北部等地有较强降雨过程，部分地区累计雨量较大，需加强次生灾害防御，做好交通、旅游、城市运行等安全管理。15日至19日，新一轮冷空气将自西向东影响我国大部地区，带来大风降温和降水天气，注意防范对交通运输、农业、城市运行等的影响，并做好森林草原和城乡防火工作。",
