    "content": "新华社乌鲁木齐10月14日电（记者潘莹、宿传义、高晗）金秋十月，天山南北棉花吐絮，迎来采收。在塔克拉玛干沙漠北缘的尉犁县“超级棉田”，伴随着一台台采棉机来回穿梭，洁白的棉花被采摘、压缩、打包，朵絮归仓。 “前不久，田里用上一款新款农业无人机，不需要飞手操作，棉花采收环节更加智能化。”“超级棉田”项目负责人艾海鹏说。 新疆是中国最大优质棉花生产基地，2025年新疆棉花产量占全国产量的92.8%，总产、单产连续32年居全国第一。如今，在新疆，这样的智慧化场景正逐渐贯穿棉花生产全过程，并加速从示范走向普及，一批懂技术、善…"
