    "title": "烟霾弥漫 印尼近两月呼吸道急症超28万例",
    "link": "http://www.news.cn/20261015/a053de61b1e841aa872c41b4ee0a55e2/c.html",
    "pub_date": "2026-10-15 07:49:54",
    "author": "沈敏",
    "description": "新华社北京10月14日电 印度尼西亚卫生部14日通报，受近期烟霾影响，近两个月来该国相关地区呼吸道感染病例激增，截至13日已报告超过28万例。 印尼一名卫生部官员在当天新闻发布会上说，8月18日至10月13日，印尼受烟霾影响地区共记录283270例呼吸道感染病例。 近几周来，印尼多地持续受到林火和烟霾影响，部分地区空气质量达到“危险”级别。印尼每到天气干燥季节便常发林火，而今年受厄尔尼诺现象影响，林火灾害尤其严重。另外，林业和生态学专家…",
    "content": "新华社北京10月14日电 印度尼西亚卫生部14日通报，受近期烟霾影响，近两个月来该国相关地区呼吸道感染病例激增，截至13日已报告超过28万例。 印尼一名卫生部官员在当天新闻发布会上说，8月18日至10月13日，印尼受烟霾影响地区共记录283270例呼吸道感染病例。 近几周来，印尼多地持续受到林火和烟霾影响，部分地区空气质量达到“危险”级别。印尼每到天气干燥季节便常发林火，而今年受厄尔尼诺现象影响，林火灾害尤其严重。另外，林业和生态学专家指出，印尼多地烧荒开垦的做法也改变了土壤环境，增加了林火风险。 10月13日，在…"
