    "content": "新华社科威特城10月14日电（记者尹炣）萨那消息：也门胡塞武装14日晚说，该组织向沙特阿拉伯首都利雅得的哈立德国王国际机场再次发射一枚弹道导弹，并向也门南部的政府军目标发射三枚弹道导弹。 胡塞武装发言人叶海亚·萨雷亚在社交媒体发表声明说，胡塞武装使用一枚弹道导弹袭击了利雅得哈立德国王国际机场，并称导弹“精准、直接”命中目标。 萨雷亚说，在另一次袭击中，胡塞武装向也门南部拉赫季省的也门政府军集结地发射了三枚弹道导弹。袭击造成政府军大量人员伤亡，并损坏数辆军用车辆。 当天稍早时候，沙特主导的多国联军说，已拦截并摧毁一枚…"
