    "content": "14/10/2026 - 23:38 欧盟各国领导人将于周四（10月15日）齐聚布鲁塞尔举行峰会。围绕下一轮多年期预算的规模和支出重点，各国分歧预计将在会上凸显，短期内料难达成协议。 欧盟预算用于支持各项共同政策，包括扶持农业、支持与中国和美国竞争的产业、推动技术进步，以及支付欧盟官员薪酬、援助乌克兰等。预算谈判历来是布鲁塞尔争议最激烈的议题之一。 多年期预算必须获得所有成员国一致同意才能通过。 目前讨论的预算涵盖2028年至2034年。能源价格上涨和国防支出增加，正使成员国公共财政承受更大压力，也令本轮谈判更加棘…"
