    "content": "14/10/2026 - 23:33 也门外交部长周三（10月14日）表示，也门政府已就亲伊朗的胡塞武装可能试图利用中国技术和零部件制造武器、用于也门冲突一事，向中国提出关切。 法新社报道，也门外长祖巴周三在有关也门冲突升级的线上记者会上，回答法新社记者关于胡塞武装可能采购中国零部件制造武器的提问时表示：“中国是我们的伙伴，我们已同他们讨论了军民两用产品的使用问题。” 也门外长表示：“中方非常希望获取各方面的信息，以便展开调查。中方对也门政府的支持是明确的。” 研究机构“冲突武器研究组织”（CAR）最近发布的一份报…"
