    "title": "欧盟担忧中国供应风险 拟与越南扩大关键矿产合作 - RFI - 法国国际广播电台",
    "link": "https://www.rfi.fr/cn/%E4%B8%AD%E5%9B%BD/20261014-%E6%AC%A7%E7%9B%9F%E6%8B%85%E5%BF%A7%E4%B8%AD%E5%9B%BD%E4%BE%9B%E5%BA%94%E9%A3%8E%E9%99%A9-%E6%8B%9F%E4%B8%8E%E8%B6%8A%E5%8D%97%E6%89%A9%E5%A4%A7%E5%85%B3%E9%94%AE%E7%9F%BF%E4%BA%A7%E5%90%88%E4%BD%9C",
    "pub_date": "2026-10-15 05:45:03",
    "author": "",
    "description": "14/10/2026 - 23:29 路透社取得的欧盟内部文件显示，出于对关键矿产供应风险的担忧，欧盟正寻求加强与越南的合作，拓宽钨、稀土和锑等国防及工业原料的供应来源，降低对中国的依赖。 越南拥有丰富的关键矿产资源，包括钨、稀土、锑、铋和铝土矿。其中，铝土矿在提炼过程中还可产出副产品镓。目前，越南向欧盟出口的矿产主要限于钨和锑。这两种矿产都用于国防领域，包括生产弹药和炸药。 欧盟驻河内代表团的一份报告指出：“越南拥有丰富的稀土和钨储量…",
    "content": "14/10/2026 - 23:29 路透社取得的欧盟内部文件显示，出于对关键矿产供应风险的担忧，欧盟正寻求加强与越南的合作，拓宽钨、稀土和锑等国防及工业原料的供应来源，降低对中国的依赖。 越南拥有丰富的关键矿产资源，包括钨、稀土、锑、铋和铝土矿。其中，铝土矿在提炼过程中还可产出副产品镓。目前，越南向欧盟出口的矿产主要限于钨和锑。这两种矿产都用于国防领域，包括生产弹药和炸药。 欧盟驻河内代表团的一份报告指出：“越南拥有丰富的稀土和钨储量。考虑到欧洲需要尽快重新武装并降低风险，越南作为关键原料潜在供应方的地位不容忽视…"
