    "content": "14/10/2026 - 22:58 美国国土安全部（DHS）正式敲定新规，取消部分外籍人士在等待工作许可证续期期间，自动延长工作资格的安排。 新规刊登于《联邦公报》，延续2025年实施的临时措施。 2025年10月30日或之后提交相关续期申请的人士，一般不能再单凭申请仍在审理中，继续使用原有工作许可证工作。 新规主要影响部分H-4签证配偶、政治庇护申请人，以及正在申请调整身份、准备取得美国永久居留权的移民。若原有工作许可证到期时，续期申请仍未获批，而申请人又没有其他有效工作资格或适用的延期安排，便可能需要暂停工作…"
