    "content": "14/10/2026 - 21:26 10月13日星期二，在法国，数百家超市在前一天遭受网络攻击后，目前正在进行清理工作。此次攻击影响了冰箱的温度控制系统；黑客设法提高了这些冰箱内的温度，有的甚至高达摄氏50度。 控制系统无处不在；在所有大型企业中，成千上万甚至数百万台设备都以这种方式运行，尤其出于管理合理化的考虑。专门从事网络威胁检测的Filigran公司创始人Samuel Hassine解释道。 “例如，在所有主要行业中，水处理行业、能源相关行业，甚至是生产线，都存在大量的联网设备。” 其他类型的攻击也可能发生…"
