    "pub_date": "2026-10-15 02:13:34",
    "author": "labay",
    "description": "弄了小半个月，三天 5 头 注册一次都注册不了，到处查攻略，有的人一顿乱填都能过，想不明白，直到我反向问 Claude 美国企业怎么做 KYC ，发现甲骨文对接的 Cybersource ，走的 AVS 认证，而国内的银行是没有对接 AVS 的，也就是说他是没办法验证姓名、账单地址的，全凭其他信息瞎猜（ ip ，设备指纹，定位，申请频率等等） 但我还是没有通过🥲 https://i.imgur.com/n9bmuO1.jpeg",
    "content": "弄了小半个月，三天 5 头 注册一次都注册不了，到处查攻略，有的人一顿乱填都能过，想不明白，直到我反向问 Claude 美国企业怎么做 KYC ，发现甲骨文对接的 Cybersource ，走的 AVS 认证，而国内的银行是没有对接 AVS 的，也就是说他是没办法验证姓名、账单地址的，全凭其他信息瞎猜（ ip ，设备指纹，定位，申请频率等等） 但我还是没有通过🥲 https://i.imgur.com/n9bmuO1.jpeg"
