    "content": "新华社内罗毕10月14日电（记者葛晨 由荟圆）肯尼亚卫生部14日确认该国出现第二例本迪布焦型埃博拉病例。患者此前已作为首例病例的密切接触者处于强制隔离和每日医学监测中。 肯尼亚卫生部在当天发表新闻公报说，肯尼亚目前累计确诊两例，死亡一例。 公报说，第二名患者为39岁男性，是首例病例的近亲属，13日出现发热、乏力和关节疼痛等症状。隔离点工作组随即对他实施单独隔离并采集样本送检，实验室检测结果为阳性。患者目前已被转入指定治疗中心。 公报说，这两例病例相互关联，没有证据显示病毒在更广泛的社区传播。肯尼亚卫生部已登记首例病…"
