    "content": "新华社帕拉马里博10月14日电（记者周永穗）苏里南副总统格雷戈里·鲁斯兰13日说，中资企业在当地很好地履行了社会责任，为该国高等教育发展作出贡献。 鲁斯兰当天在中资企业社会责任项目苏里南大学学术报告厅焕新启用仪式上说：“我们高度赞赏中资企业与苏里南大学的这项合作投资，这为师生打造了一个理想的学习与工作环境。” “50年前，我也曾在这里的教室里学习。”曾就读于苏里南大学的鲁斯兰说，“今天这些设施的改善，将在学生们心中留下深刻印记。这段美好的共同记忆，必将为未来苏中友好与务实合作奠定更加坚实的基础。” 据介绍，报告厅焕…"
