    "content": "中新社北京10月14日电 (记者 刘文文)今年以来，面对复杂严峻的全球经贸形势，中国外贸运行总体平稳、韧性强劲。中国-东盟首席商务专家许宁宁14日接受记者采访时表示，中国与《区域全面经济伙伴关系协定》(RCEP)成员国贸易往来持续深化，成为稳外贸、优布局的重要支撑。"
