    "author": "李佳旭",
    "description": "10月10日，在巴拿马科克莱省佩诺诺梅市阿基利诺·特黑拉医院外的临时安置点，当地一家面包店的员工为医患分发面包和饮用水（视频截图）。新华社记者 李佳旭 摄 新华社巴拿马佩诺诺梅10月14日电 记者手记｜下雨的灾区，老乡的面包店 新华社记者李佳旭 十月的巴拿马仍处于雨季。10日那天下午的1时许，科克莱省佩诺诺梅市突降大雨。在建筑受损的阿基利诺·特黑拉医院外，密集雨点砸在帐篷上，又顺着缝隙落在医生、患者、救援队员和警察身上。 9日中午发生的…",
    "content": "10月10日，在巴拿马科克莱省佩诺诺梅市阿基利诺·特黑拉医院外的临时安置点，当地一家面包店的员工为医患分发面包和饮用水（视频截图）。新华社记者 李佳旭 摄 新华社巴拿马佩诺诺梅10月14日电 记者手记｜下雨的灾区，老乡的面包店 新华社记者李佳旭 十月的巴拿马仍处于雨季。10日那天下午的1时许，科克莱省佩诺诺梅市突降大雨。在建筑受损的阿基利诺·特黑拉医院外，密集雨点砸在帐篷上，又顺着缝隙落在医生、患者、救援队员和警察身上。 9日中午发生的7.5级地震，以及数百次余震，让佩诺诺梅市所在的巴拿马中部地区上千处住宅受损，多…"
