    "description": "新华社巴黎10月14日电（记者崔可欣）国际能源署14日发布月度石油市场报告说，受中东和俄罗斯柴油出口持续受阻等因素影响，全球柴油市场供应紧张局面加剧，库存持续下降，柴油供应紧张态势预计将持续至2027年。 报告说，今年第三季度全球柴油市场出现供应紧张，冬季需求高峰到来前的库存缓冲明显不足。今年前9个月，受炼油厂产量下降影响，全球柴油出口量为日均470万桶，同比下降10%。柴油市场供需形势能否改善，很大程度上取决于中东地区成品油供应能否恢…",
    "content": "新华社巴黎10月14日电（记者崔可欣）国际能源署14日发布月度石油市场报告说，受中东和俄罗斯柴油出口持续受阻等因素影响，全球柴油市场供应紧张局面加剧，库存持续下降，柴油供应紧张态势预计将持续至2027年。 报告说，今年第三季度全球柴油市场出现供应紧张，冬季需求高峰到来前的库存缓冲明显不足。今年前9个月，受炼油厂产量下降影响，全球柴油出口量为日均470万桶，同比下降10%。柴油市场供需形势能否改善，很大程度上取决于中东地区成品油供应能否恢复。 报告预计，受中东局势导致石油产品供应受限、燃料价格飙升以及经济前景恶化影响…"
