    "content": "新华社北京10月14日电 人民日报10月15日评论员文章：建成均衡普惠、优质高效的健康中国——论学习贯彻习近平总书记在全国卫生与健康大会上重要讲话 “我们要建成的健康中国，是均衡普惠、优质高效的健康中国”。 在全国卫生与健康大会上，习近平总书记着眼于人民健康在党和国家事业发展中的重要地位，科学分析我国卫生与健康事业发展面临的形势，系统阐明了建成健康中国的目标任务、基本内涵，为实现到2035年建成健康中国目标提供重要指引。 人民健康是社会文明进步的基础，人人健康是老百姓美好的愿望和热切的期盼。我们党是全心全意为人民服…"
