    "author": "Arispex",
    "description": "前段时间分享了一个自己开发的 iOS 原生翻译软件： https://v2ex.com/t/1246740?p=1#reply39 当天收到了一封邮件 TestFlight 版本目前只在这里分享过，所以肯定是 v 友干的，也不排除有机器人专门扫（？ 笑点解析： 软件的中文名称（纯粹翻译）和英文名称（ Crosslate ）是对不上的，但是邮件中出现的软件名称是 purely for translation，很明显是直译的",
    "content": "前段时间分享了一个自己开发的 iOS 原生翻译软件： https://v2ex.com/t/1246740?p=1#reply39 当天收到了一封邮件 TestFlight 版本目前只在这里分享过，所以肯定是 v 友干的，也不排除有机器人专门扫（？ 笑点解析： 软件的中文名称（纯粹翻译）和英文名称（ Crosslate ）是对不上的，但是邮件中出现的软件名称是 purely for translation ，很明显是直译的"
